using System;using System.Collections.Generic;using System.IO;using System.Xml.Serialization;using ScreenDock;
class PresetTests {
 static void Check(bool x,string m){if(!x)throw new Exception(m);}
 static void Reject(Action a){bool rejected=false;try{a();}catch(Exception){rejected=true;}Check(rejected,"unsafe plan accepted");}
 static void Main(){var a=new Display{Device="newA",Identity="monitorA",Active=true,Primary=true,Mode=new Native.Mode{width=1920,height=1080}};var b=new Display{Device="newB",Identity="monitorB",Active=true,Mode=new Native.Mode{width=2560,height=1440,x=1920}};var current=new List<Display>{a,b};var preset=new ScreenPreset{Name="办公"};preset.Screens.Add(new PresetScreen{Identity=a.Identity,Active=true,Primary=true,Mode=a.Mode,Brightness=60});preset.Screens.Add(new PresetScreen{Identity=b.Identity,Active=false,Mode=b.Mode});var serializer=new XmlSerializer(typeof(ScreenPreset));using(var ms=new MemoryStream()){serializer.Serialize(ms,preset);ms.Position=0;preset=(ScreenPreset)serializer.Deserialize(ms);}Check(preset.Screens[0].Brightness==60&&!preset.Screens[1].Brightness.HasValue,"brightness roundtrip");var plan=Presets.Plan(preset,current);Check(plan.ContainsKey("newA")&&plan["newB"].width==0,"identity rebinding and disable");Reject(()=>Presets.Plan(preset,new List<Display>{a}));b.Identity="other";Reject(()=>Presets.Plan(preset,current));b.Identity="monitorB";a.Primary=false;b.Primary=true;Reject(()=>Presets.Plan(preset,current));a.Primary=true;b.Primary=false;preset.Screens[0].Active=false;Reject(()=>Presets.Plan(preset,current));preset.Screens[0].Active=true;preset.Screens[0].Brightness=101;Reject(()=>Presets.Plan(preset,current));Console.WriteLine("PASS: XML roundtrip, identity mapping, disabled mode, missing/replaced screens, changed primary, primary protection, brightness validation. No hardware writes.");}
}
